select jsonb_build_object('at',statement_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','collection',(select to_jsonb(c) from public.collections c where id=976400001),'members',(select jsonb_agg(to_jsonb(b) order by work_id) from public.collection_books b where collection_id=976400001),'foreignKeys',(select jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'target',confrelid::regclass::text,'definition',pg_get_constraintdef(oid))) from pg_constraint where contype='f' and confrelid in('public.collections'::regclass,'public.collection_books'::regclass)),'publicDigests',jsonb_build_object('works',(select jsonb_build_object('n',count(*),'md5',md5(string_agg(to_jsonb(w)::text,'|' order by id)))from public.works w),'editions',(select jsonb_build_object('n',count(*),'md5',md5(string_agg(to_jsonb(e)::text,'|' order by id)))from public.editions e),'metadata',(select jsonb_build_object('n',count(*),'md5',md5(string_agg(to_jsonb(e)::text,'|' order by edition_id)))from public.catalog_edition_metadata e),'texts',(select jsonb_build_object('n',count(*),'md5',md5(string_agg(to_jsonb(e)::text,'|' order by work_id,language)))from public.catalog_work_descriptions e),'otherCollections',(select jsonb_build_object('n',count(*),'md5',md5(string_agg(to_jsonb(c)::text,'|' order by id)))from public.collections c where id<>976400001),'otherMembers',(select jsonb_build_object('n',count(*),'md5',md5(string_agg(to_jsonb(c)::text,'|' order by collection_id,work_id)))from public.collection_books c where collection_id<>976400001)),'protected',jsonb_build_object('ratings',(select jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(r)::text,'|' order by to_jsonb(r)::text)))from public.ratings r),'statuses',(select jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(s)::text,'|' order by to_jsonb(s)::text)))from public.user_book_status s),'accounts',(select jsonb_build_object('count',count(*),'digest',md5(string_agg(id::text||':'||created_at::text,'|' order by id)))from auth.users))) as snapshot;
